// Dart 变量与空安全入门示例
// 运行方式：dart run null_safety_demo.dart

void main() {
  // 1. var：类型推断，类型在首次赋值后固定
  var name = 'Flutter';
  // name = 42; // ❌ 编译错误：name 的类型已被推断为 String
  print('1. var -> $name');

  // 2. final：运行时确定、只能赋值一次
  final DateTime now = DateTime.now();
  print('2. final -> ${now.toIso8601String()}');

  // 3. const：编译期常量，必须是字面量或常量表达式
  const int maxRetry = 3;
  const String tag = '[Demo]';
  print('3. const -> $tag maxRetry = $maxRetry');

  // 4. 可空类型：用 ? 声明变量可以为 null
  String? nickname; // 未赋值，默认为 null
  print('4. nickname = $nickname');

  // 5. 空感知 + 空合并：?. 和 ??
  final int length = nickname?.length ?? 0;
  print('5. 长度 -> $length');

  // 6. 赋值后可以安全使用；! 是非空断言（谨慎使用）
  nickname = 'Dart';
  print('6. 非空断言 -> ${nickname!.toUpperCase()}');

  // 7. ?? 提供默认值，避免 null 流入 UI
  final String displayName = nickname ?? '匿名用户';
  print('7. displayName -> $displayName');

  // 8. 实战：解析可能缺字段的 JSON（Map）
  final Map<String, dynamic> json = {'id': 7, 'name': '小明'};
  final int userId = json['id'] as int? ?? -1;
  final String userName = json['name'] as String? ?? '未知';
  final String email = json['email'] as String? ?? '未填写';
  print('8. 解析结果 -> id: $userId, name: $userName, email: $email');
}

